export const MORE_INFO_TEMPLATE_KEY = 'more_info_after_call' as const;
export const EMAIL_LOGO_PATH = '/images/email/homequote-logo-transparent.png';

export interface EmailTemplateProspect {
  company_name: string;
}

function clean(value: string): string {
  return value.replace(/[_-]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function servicePhrase(services: string[]): string | null {
  const values = Array.from(new Set(services.map(clean).filter(Boolean))).slice(0, 5);
  if (values.length === 0) return null;
  if (values.length === 1) return values[0];
  if (values.length === 2) return `${values[0]} and ${values[1]}`;
  return `${values.slice(0, -1).join(', ')}, and ${values.at(-1)}`;
}

export function emailLogoUrl(siteUrl: string): string {
  return new URL(EMAIL_LOGO_PATH, siteUrl.endsWith('/') ? siteUrl : `${siteUrl}/`).toString();
}

export function buildMoreInfoAfterCallEmail(
  prospect: EmailTemplateProspect,
  contactName: string,
  discussedServices: string[]
): { subject: string; message: string } {
  const company = clean(prospect.company_name);
  const firstName = clean(contactName).split(' ')[0] || '';
  const greeting = firstName ? `Hi ${firstName},` : 'Hi,';
  const services = servicePhrase(discussedServices);

  return {
    subject: `Following up after our call${company ? ` — ${company}` : ''}`,
    message: [
      greeting,
      '',
      `Thanks again for taking my call. I wanted to follow up with a little more detail on how HomeQuote Network could work with ${company}.`,
      '',
      'We speak directly with homeowners about their pool projects, qualify the project by confirming the details and fit, and then book a specific day and time for the contractor to meet with the homeowner.',
      ...(services
        ? [
            '',
            `Based on our conversation, we would focus on homeowners looking for ${services}.`,
          ]
        : []),
      '',
      'If that sounds worth exploring, would you be open to a 15-minute call with Liam?',
      '',
      'You can also book an appointment with Liam and see our results at https://homequotenet.com/.',
    ].join('\n'),
  };
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function messageHtml(message: string): string {
  return message
    .trim()
    .split(/\n{2,}/)
    .map((paragraph) => {
      const content = escapeHtml(paragraph)
        .replace(
          /https:\/\/homequotenet\.com\/?/gi,
          '<a href="https://homequotenet.com/" style="color:#0038B8;text-decoration:underline;">homequotenet.com</a>'
        )
        .replace(/\n/g, '<br>');
      return `<p style="margin:0 0 16px 0;">${content}</p>`;
    })
    .join('');
}

/** Who signs a prospect email: the team member sending it (Liam by default). */
export interface EmailSigner {
  name: string;
  phone?: string | null;
}

export const DEFAULT_SIGNER: EmailSigner = { name: 'Liam' };

/**
 * Required in commercial email (CAN-SPAM, B2B included): a way to opt out and
 * the sender's postal address. The address comes from EMAIL_MAILING_ADDRESS
 * (server env); without it only the opt-out line is shown.
 */
export const OPT_OUT_LINE = 'Not interested in hearing from us? Reply "stop" and we won\u2019t email you again.';

export function mailingAddress(): string | null {
  const v = typeof process !== 'undefined' ? process.env.EMAIL_MAILING_ADDRESS : undefined;
  return v && v.trim() ? v.trim() : null;
}

function signerName(signer: EmailSigner | null | undefined): string {
  const name = signer?.name?.trim();
  return name ? name : DEFAULT_SIGNER.name;
}

/** Gmail-safe, inline-styled HTML used verbatim by both preview and delivery. */
export function buildProspectEmailHtml(
  message: string,
  logoUrl: string,
  signer: EmailSigner = DEFAULT_SIGNER,
  address: string | null = null
): string {
  const safeLogoUrl = escapeHtml(logoUrl);
  const phone = signer.phone?.trim();
  return [
    '<div style="margin:0;padding:0;background:#ffffff;color:#0A1B3D;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.65;">',
    '<div style="max-width:600px;margin:0;padding:4px 0;">',
    messageHtml(message),
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin-top:24px;border-top:1px solid #DCE4F2;padding-top:16px;border-collapse:separate;">',
    '<tr>',
    `<td style="padding:0 14px 0 0;vertical-align:middle;"><img src="${safeLogoUrl}" width="72" height="72" alt="HomeQuote Network" style="display:block;width:72px;height:72px;border:0;outline:none;text-decoration:none;"></td>`,
    '<td style="padding:0;vertical-align:middle;font-family:Arial,Helvetica,sans-serif;line-height:1.4;">',
    `<div style="font-size:16px;font-weight:700;color:#0A1B3D;">${escapeHtml(signerName(signer))}</div>`,
    '<div style="font-size:14px;font-weight:700;color:#0038B8;">HomeQuote Network</div>',
    phone ? `<div style="font-size:13px;color:#0A1B3D;">${escapeHtml(phone)}</div>` : '',
    '<div style="font-size:13px;color:#5B6B8C;">Homeowner qualification &amp; pool project appointments</div>',
    '</td>',
    '</tr>',
    '</table>',
    `<p style="margin:20px 0 0 0;font-size:12px;line-height:1.5;color:#8A96B0;">${escapeHtml(OPT_OUT_LINE)}${
      address ? `<br>HomeQuote Network · ${escapeHtml(address)}` : ''
    }</p>`,
    '</div>',
    '</div>',
  ].join('');
}

export function buildProspectEmailText(
  message: string,
  signer: EmailSigner = DEFAULT_SIGNER,
  address: string | null = null
): string {
  const phone = signer.phone?.trim();
  return [
    message.trim(),
    '',
    'Best,',
    signerName(signer),
    'HomeQuote Network',
    ...(phone ? [phone] : []),
    '',
    '--',
    OPT_OUT_LINE,
    ...(address ? [`HomeQuote Network · ${address}`] : []),
  ].join('\n');
}

// ---------------------------------------------------------------------------
// Branded shell for the email template library (lib/emails/template-library.ts).
// Used once at seed time to produce each template's stored html_body/text_body;
// after that the stored HTML is what admins edit and what gets rendered with
// live variables (see lib/emails/variables.ts). Keep this Gmail-safe: inline
// styles only, no external stylesheet, table-based layout for the footer.
// ---------------------------------------------------------------------------
export interface BrandedEmailOptions {
  logoUrl: string;
  ctaText?: string;
  ctaUrl?: string;
  footerNote?: string;
}

function paragraphsHtml(paragraphs: string[]): string {
  return paragraphs
    .map((paragraph) => `<p style="margin:0 0 16px 0;">${escapeHtml(paragraph).replace(/\n/g, '<br>')}</p>`)
    .join('');
}

export function buildBrandedEmailHtml(paragraphs: string[], options: BrandedEmailOptions): string {
  const safeLogoUrl = escapeHtml(options.logoUrl);
  const cta =
    options.ctaText && options.ctaUrl
      ? `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 20px 0;"><tr><td style="border-radius:8px;background:#0038B8;"><a href="${escapeHtml(options.ctaUrl)}" style="display:inline-block;padding:12px 22px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:8px;">${escapeHtml(options.ctaText)}</a></td></tr></table>`
      : '';
  return [
    '<div style="margin:0;padding:0;background:#ffffff;color:#0A1B3D;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.65;">',
    '<div style="max-width:600px;margin:0;padding:4px 0;">',
    `<img src="${safeLogoUrl}" width="40" height="40" alt="HomeQuote Network" style="display:block;width:40px;height:40px;margin-bottom:20px;border:0;outline:none;text-decoration:none;">`,
    paragraphsHtml(paragraphs),
    cta,
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin-top:16px;border-top:1px solid #DCE4F2;padding-top:16px;border-collapse:separate;">',
    '<tr><td style="padding:0;vertical-align:middle;font-family:Arial,Helvetica,sans-serif;line-height:1.4;">',
    '<div style="font-size:14px;font-weight:700;color:#0038B8;">HomeQuote Network</div>',
    `<div style="font-size:13px;color:#5B6B8C;">${escapeHtml(options.footerNote ?? 'Homeowner qualification & contractor appointments')}</div>`,
    '</td></tr>',
    '</table>',
    '</div>',
    '</div>',
  ].join('');
}

export function buildBrandedEmailText(paragraphs: string[], options: { footerNote?: string } = {}): string {
  return `${paragraphs.join('\n\n')}\n\n—\nHomeQuote Network\n${options.footerNote ?? 'homequotenet.com'}`;
}
